package io.github.astelev.around_planet.gametest;
import io.github.astelev.around_planet.client.*;
import io.github.astelev.around_planet.space.*;
import io.github.astelev.around_planet.network.*;
import io.github.astelev.around_planet.maneuver.ManeuverRegistry;
import net.minecraft.client.Minecraft;
import net.minecraft.core.BlockPos;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.phys.*;
import net.minecraft.core.Direction;
import net.minecraft.client.gui.components.*;
import net.neoforged.neoforge.network.PacketDistributor;
import dev.ryanhcode.sable.sublevel.ServerSubLevel;
import java.util.*;
final class ManeuverClientSmoke {
    private static int ticks,stage,at;private static volatile Throwable failure;private static BlockPos block;private static UUID focus,session;private static volatile SpaceTrajectory original;private static ManeuverNode node;
    static void tick(Minecraft mc,ServerSubLevel ship){
        if(stage==9)return;ticks++;if(failure!=null)throw new AssertionError("Maneuver server fixture",failure);if(ticks>1600)throw new AssertionError("Maneuver smoke timeout stage="+stage);
        if(stage==0){stage=1;at=ticks;server(mc,()->{var level=ship.getLevel();var cell=SpaceCells.get(level).forShip(ship.getUniqueId());focus=cell.id();var data=SpaceOrbitData.get(level.getServer());double radius=data.navigation(focus).orElseThrow().planet().radius(),r=radius+8000,mu=9.81*radius*radius;
            original=new SpaceTrajectory("around_planet:overworld",level.getGameTime(),new SpaceState(new SpaceVector(r,0,0),new SpaceVector(0,Math.sqrt(mu/r),0)),mu);data.put(focus,original);io.github.astelev.around_planet.compat.SpaceReentry.entered(level,focus,original.initial().position());dev.ryanhcode.sable.api.sublevel.SubLevelContainer.getContainer(level).physicsSystem().setPaused(true);
            var box=ship.getPlot().getBoundingBox();block=new BlockPos(box.minX(),box.minY()+2,box.minZ());level.setBlockAndUpdate(block,ManeuverRegistry.PLANNER.get().defaultBlockState());var p=level.players().getFirst();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.STICK));p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);var result=level.getBlockState(block).useWithoutItem(level,p,new BlockHitResult(Vec3.atCenterOf(block),Direction.UP,block,false));require(result==net.minecraft.world.InteractionResult.PASS,"Held item opened planner");p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.TORCH));result=level.getBlockState(block).useWithoutItem(level,p,new BlockHitResult(Vec3.atCenterOf(block),Direction.UP,block,false));require(result==net.minecraft.world.InteractionResult.PASS,"Offhand item opened planner");p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);use(ship);});return;}
        if(ticks-at<35)return;
        if(stage==1){if(!(mc.screen instanceof OrbitMapScreen))return;var p=ManeuverClient.current();require(p!=null&&!p.session().equals(ManeuverPayload.NONE),"No server editor grant");session=p.session();var screen=(OrbitMapScreen)mc.screen;clickOrbit(screen);stage=2;at=ticks;return;}
        if(stage==2){var p=ManeuverClient.current();if(p==null||p.nodes().size()!=1)return;var fields=mc.screen.children().stream().filter(EditBox.class::isInstance).map(EditBox.class::cast).toList();require(fields.size()==3,"Planner axis fields missing");fields.get(0).setValue("25");fields.get(1).setValue("-5");fields.get(2).setValue("10");stage=3;at=ticks;return;}
        if(stage==3){var p=ManeuverClient.current();if(p.nodes().size()!=1||p.nodes().getFirst().prograde()!=25||p.nodes().getFirst().normal()!=-5||p.nodes().getFirst().radial()!=10)return;node=p.nodes().getFirst();var preview=preview((OrbitMapScreen)mc.screen);require(preview.segments().stream().anyMatch(ManeuverPreview.Segment::planned),"No post-burn curve");var last=preview.segments().getLast().points().getLast();require(last.position().subtract(p.trajectory().at(last.tick()).position()).length()>10,"Preview ignored delta-v");snap(mc,"maneuver-editor-alpha27.png");server(mc,()->{var data=SpaceOrbitData.get(mc.getSingleplayerServer());require(data.get(focus).orElseThrow().equals(original),"Planning executed a real burn");var copy=SpaceOrbitData.load(data.save(new net.minecraft.nbt.CompoundTag(),ship.getLevel().registryAccess()),ship.getLevel().registryAccess());require(copy.maneuvers(focus).equals(List.of(node)),"Plan did not persist");});mc.screen.onClose();stage=4;at=ticks;return;}
        if(stage==4){mc.setScreen(new OrbitMapScreen());stage=5;at=ticks;return;}
        if(stage==5){require(mc.screen.children().stream().noneMatch(EditBox.class::isInstance),"Ordinary map contains edit controls");require(ManeuverClient.current().nodes().size()==1,"Ordinary map lost saved node");require(!preview((OrbitMapScreen)mc.screen).nodes().isEmpty(),"Ordinary map lacks node marker");snap(mc,"maneuver-readonly-alpha27.png");PacketDistributor.sendToServer(new ManeuverPayload.Edit(session,999,false,new ManeuverNode(node.id(),node.tick(),999,0,0)));stage=6;at=ticks;return;}
        if(stage==6){require(ManeuverClient.current().nodes().getFirst().prograde()==25,"Closed session accepted forged edit");mc.screen.onClose();stage=61;at=ticks;return;}
        if(stage==61){server(mc,()->use(ship));stage=7;at=ticks;return;}
        if(stage==7){if(!(mc.screen instanceof OrbitMapScreen screen))return;require(!ManeuverClient.current().session().equals(session),"Editor reused revoked session");var mark=preview(screen).nodes().getFirst();var point=project(screen,mark.position());screen.mouseClicked(point.x(),point.y(),0);screen.mouseReleased(point.x(),point.y(),0);var fields=screen.children().stream().filter(EditBox.class::isInstance).map(EditBox.class::cast).toList();require(Double.parseDouble(fields.get(0).getValue())==25,"Reopened planner lost delta-v");screen.children().stream().filter(Button.class::isInstance).map(Button.class::cast).filter(b->b.getMessage().getString().equals(net.minecraft.network.chat.Component.translatable("around_planet.maneuver.delete").getString())).findFirst().orElseThrow().onPress();stage=8;at=ticks;return;}
        if(stage==8){if(!ManeuverClient.current().nodes().isEmpty())return;mc.screen.onClose();stage=9;io.github.astelev.around_planet.AroundPlanet.LOGGER.info("MANEUVER_PLANNER PASS empty hands, server grant, orbit click, signed axes, predicted curve, persistence, read-only M map, revoked-session rejection, reopen and delete");mc.stop();}
    }
    private static void use(ServerSubLevel ship){var level=ship.getLevel();var p=level.players().getFirst();level.getBlockState(block).useWithoutItem(level,p,new BlockHitResult(Vec3.atCenterOf(block),Direction.UP,block,false));}
    private static void clickOrbit(OrbitMapScreen screen){try{var visible=OrbitMapScreen.class.getDeclaredMethod("visible",SpaceVector.class);visible.setAccessible(true);var p=ManeuverClient.current();var curve=OrbitPlot.create(p.trajectory().at(ManeuverClient.now()),p.trajectory().mu(),SpaceHud.current().radius(),SpaceHud.current().returnAltitude(),false);for(double f:new double[]{.12,.2,.32,.45,.58,.7,.85}){var point=p.trajectory().at(ManeuverClient.now()+(long)(curve.period()*20*f)).position();if(!(Boolean)visible.invoke(screen,point))continue;var xy=project(screen,point);screen.mouseClicked(xy.x(),xy.y(),0);screen.mouseReleased(xy.x(),xy.y(),0);return;}throw new AssertionError("No visible orbit hit target");}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    private static OrbitCamera.Point project(OrbitMapScreen screen,SpaceVector p){try{var method=OrbitMapScreen.class.getDeclaredMethod("project",SpaceVector.class);method.setAccessible(true);return (OrbitCamera.Point)method.invoke(screen,p);}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    private static ManeuverPreview preview(OrbitMapScreen screen){try{var f=OrbitMapScreen.class.getDeclaredField("maneuvers");f.setAccessible(true);var layer=f.get(screen);f=layer.getClass().getDeclaredField("preview");f.setAccessible(true);return (ManeuverPreview)f.get(layer);}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    private static void server(Minecraft mc,Runnable task){mc.getSingleplayerServer().execute(()->{try{task.run();}catch(Throwable e){failure=e;}});}
    private static void snap(Minecraft mc,String name){net.minecraft.client.Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),m->{});}
    private static void require(boolean condition,String text){if(!condition)throw new AssertionError(text);}
}
